ALTER TABLE "Product" ADD COLUMN "ageMin" INTEGER, ADD COLUMN "ageMax" INTEGER,
 ADD COLUMN "scenes" TEXT[] NOT NULL DEFAULT ARRAY[]::TEXT[], ADD COLUMN "skills" TEXT[] NOT NULL DEFAULT ARRAY[]::TEXT[], ADD COLUMN "tags" TEXT[] NOT NULL DEFAULT ARRAY[]::TEXT[], ADD COLUMN "markets" TEXT[] NOT NULL DEFAULT ARRAY[]::TEXT[],
 ADD COLUMN "publishAt" TIMESTAMP(3), ADD COLUMN "unpublishAt" TIMESTAMP(3), ADD COLUMN "specifications" JSONB NOT NULL DEFAULT '{}', ADD COLUMN "playGuide" TEXT, ADD COLUMN "productFaq" JSONB NOT NULL DEFAULT '[]', ADD COLUMN "relatedSlugs" TEXT[] NOT NULL DEFAULT ARRAY[]::TEXT[], ADD COLUMN "archiveRedirect" TEXT;
ALTER TABLE "ProductVariant" ADD COLUMN "barcode" TEXT, ADD COLUMN "marketPrices" JSONB NOT NULL DEFAULT '{}';
ALTER TABLE "Stock" ADD COLUMN "lowThreshold" INTEGER NOT NULL DEFAULT 5, ADD COLUMN "source" TEXT NOT NULL DEFAULT 'MANUAL', ADD COLUMN "sourceUpdatedAt" TIMESTAMP(3), ADD COLUMN "syncError" TEXT;
ALTER TABLE "PricingRule" ADD COLUMN "market" TEXT, ADD COLUMN "currency" TEXT NOT NULL DEFAULT 'USD', ADD COLUMN "startsAt" TIMESTAMP(3), ADD COLUMN "endsAt" TIMESTAMP(3);
ALTER TABLE "Order" ADD COLUMN "currency" TEXT NOT NULL DEFAULT 'USD', ADD COLUMN "market" TEXT NOT NULL DEFAULT 'US', ADD COLUMN "discountCents" INTEGER NOT NULL DEFAULT 0, ADD COLUMN "shippingCents" INTEGER NOT NULL DEFAULT 0, ADD COLUMN "taxCents" INTEGER NOT NULL DEFAULT 0, ADD COLUMN "couponCode" TEXT, ADD COLUMN "shippingMethod" TEXT NOT NULL DEFAULT 'STANDARD', ADD COLUMN "shippingAddress" JSONB NOT NULL DEFAULT '{}', ADD COLUMN "billingAddress" JSONB NOT NULL DEFAULT '{}', ADD COLUMN "paymentStatus" TEXT NOT NULL DEFAULT 'UNPAID', ADD COLUMN "reservationExpiresAt" TIMESTAMP(3);
ALTER TABLE "OrderItem" ADD COLUMN "shippedQuantity" INTEGER NOT NULL DEFAULT 0, ADD COLUMN "returnedQuantity" INTEGER NOT NULL DEFAULT 0;
UPDATE "OrderItem" SET "shippedQuantity"="quantity" WHERE "orderId" IN (SELECT "id" FROM "Order" WHERE "status"='FULFILLED');
CREATE TABLE "RetailMarket" ("code" TEXT PRIMARY KEY,"label" TEXT NOT NULL,"currency" TEXT NOT NULL DEFAULT 'USD',"retailEnabled" BOOLEAN NOT NULL DEFAULT true,"countries" TEXT[] NOT NULL DEFAULT ARRAY[]::TEXT[],"taxBps" INTEGER NOT NULL DEFAULT 0,"shippingCents" INTEGER NOT NULL DEFAULT 0,"expressCents" INTEGER NOT NULL DEFAULT 0,"freeShippingAboveCents" INTEGER,"reservationMinutes" INTEGER NOT NULL DEFAULT 30,"paymentMode" TEXT NOT NULL DEFAULT 'DEMO',"updatedAt" TIMESTAMP(3) NOT NULL);
CREATE TABLE "RetailCoupon" ("code" TEXT PRIMARY KEY,"market" TEXT NOT NULL DEFAULT 'US',"percentBps" INTEGER NOT NULL DEFAULT 0,"amountCents" INTEGER NOT NULL DEFAULT 0,"minimumCents" INTEGER NOT NULL DEFAULT 0,"startsAt" TIMESTAMP(3),"endsAt" TIMESTAMP(3),"maxUses" INTEGER,"uses" INTEGER NOT NULL DEFAULT 0,"active" BOOLEAN NOT NULL DEFAULT true,"updatedAt" TIMESTAMP(3) NOT NULL);
CREATE TABLE "RetailPayment" ("id" TEXT PRIMARY KEY,"orderId" TEXT NOT NULL REFERENCES "Order"("id") ON DELETE RESTRICT ON UPDATE CASCADE,"idempotencyKey" TEXT NOT NULL UNIQUE,"mode" TEXT NOT NULL,"status" TEXT NOT NULL DEFAULT 'PENDING',"amountCents" INTEGER NOT NULL,"currency" TEXT NOT NULL,"providerReference" TEXT,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL);
CREATE INDEX "RetailPayment_orderId_idx" ON "RetailPayment"("orderId");
CREATE TABLE "RetailPaymentEvent" ("eventId" TEXT PRIMARY KEY,"paymentId" TEXT NOT NULL,"status" TEXT NOT NULL,"payloadHash" TEXT NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE "RetailShipment" ("id" TEXT PRIMARY KEY,"orderId" TEXT NOT NULL REFERENCES "Order"("id") ON DELETE RESTRICT ON UPDATE CASCADE,"idempotencyKey" TEXT NOT NULL UNIQUE,"carrier" TEXT NOT NULL,"trackingNumber" TEXT NOT NULL,"trackingUrl" TEXT,"items" JSONB NOT NULL,"deliveredAt" TIMESTAMP(3),"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX "RetailShipment_orderId_idx" ON "RetailShipment"("orderId");
CREATE TABLE "RetailReturn" ("id" TEXT PRIMARY KEY,"orderId" TEXT NOT NULL REFERENCES "Order"("id") ON DELETE RESTRICT ON UPDATE CASCADE,"reason" TEXT NOT NULL,"resolution" TEXT NOT NULL DEFAULT 'REFUND',"status" TEXT NOT NULL DEFAULT 'REQUESTED',"items" JSONB NOT NULL,"staffNote" TEXT,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL);
CREATE INDEX "RetailReturn_orderId_idx" ON "RetailReturn"("orderId");
CREATE TABLE "RetailRefund" ("id" TEXT PRIMARY KEY,"orderId" TEXT NOT NULL REFERENCES "Order"("id") ON DELETE RESTRICT ON UPDATE CASCADE,"returnId" TEXT,"idempotencyKey" TEXT NOT NULL UNIQUE,"amountCents" INTEGER NOT NULL,"reason" TEXT NOT NULL,"status" TEXT NOT NULL DEFAULT 'PENDING',"providerReference" TEXT,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL);
CREATE INDEX "RetailRefund_orderId_idx" ON "RetailRefund"("orderId");
CREATE TABLE "RetailPriceHistory" ("id" TEXT PRIMARY KEY,"variantId" TEXT NOT NULL,"actorId" TEXT NOT NULL,"before" JSONB NOT NULL,"after" JSONB NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX "RetailPriceHistory_variantId_createdAt_idx" ON "RetailPriceHistory"("variantId","createdAt");
ALTER TABLE "Cart" ADD COLUMN "mergeKeys" TEXT[] NOT NULL DEFAULT ARRAY[]::TEXT[];
ALTER TABLE "RetailCoupon" ADD COLUMN "freeShipping" BOOLEAN NOT NULL DEFAULT false, ADD COLUMN "productIds" TEXT[] NOT NULL DEFAULT ARRAY[]::TEXT[], ADD COLUMN "userIds" TEXT[] NOT NULL DEFAULT ARRAY[]::TEXT[], ADD COLUMN "perUserLimit" INTEGER;
ALTER TABLE "RetailPayment" ADD COLUMN "checkoutUrl" TEXT;
